//
//  TypeInfoTests.swift
//  TailspotTests
//
//  Covers the bundled card-back type data (TypeInfo.json, generated by
//  tools/generate-type-info.py) and TypeInfoStore's catch → entry → facts
//  resolution, including the AircraftTypes.json wingspan/length fallback.
//

import Testing
import Foundation
@testable import Tailspot

@Suite("Type info")
struct TypeInfoTests {

    private func mk(typecode: String?, model: String? = nil) -> Catch {
        Catch(icao24: "test\(typecode ?? model ?? "x")",
              callsign: nil, model: model, manufacturer: nil,
              caughtAt: Date(), observerLat: 0, observerLon: 0,
              slantDistanceMeters: 0, typecode: typecode)
    }

    /// Raw decode of the bundled file, independent of TypeInfoStore's cache.
    private struct File: Decodable {
        let version: Int
        let generated: String
        let entries: [String: TypeInfo]
    }

    private func bundledFile() throws -> File {
        let url = try #require(Bundle.main.url(forResource: "TypeInfo", withExtension: "json"))
        return try JSONDecoder().decode(File.self, from: Data(contentsOf: url))
    }

    // MARK: - The bundled JSON

    @Test func bundledJSONDecodes() throws {
        let file = try bundledFile()
        #expect(file.version == 1)
        #expect(file.entries.count > 250, "Expected most family entries to resolve, got \(file.entries.count)")
    }

    @Test func everyKeyIsARealFamilyEntryAndMatchesItsEntryId() throws {
        let ids = Set(CardSets.families.flatMap(\.entries).map(\.id))
        for (key, info) in try bundledFile().entries {
            #expect(ids.contains(key), "TypeInfo.json key '\(key)' is not a CardSets.families entry")
            #expect(info.entryId == key, "entryId '\(info.entryId)' != key '\(key)'")
            #expect(key != "fu-unidentified")
        }
    }

    /// The reverse direction: every family entry has a record, so a family
    /// added to Sets.swift without re-running the generator fails here
    /// instead of shipping blank card backs.
    @Test func everyFamilyEntryHasARecord() throws {
        // Entries known to have no English Wikipedia article (OVERRIDES maps
        // them to None in tools/generate-type-info.py).
        let knownMisses: Set<String> = ["fsc-harmon-rocket"]
        let keys = Set(try bundledFile().entries.keys)
        for family in CardSets.families where family.id != "fam-unidentified" {
            for entry in family.entries where !knownMisses.contains(entry.id) {
                #expect(keys.contains(entry.id),
                        "\(entry.id) has no TypeInfo.json record: re-run python3 -I tools/generate-type-info.py")
            }
        }
    }

    @Test func knownEntriesResolveWithAWikipediaTitle() {
        let b738 = TypeInfoStore.info(forEntryId: "f737-800")
        #expect(b738?.wikipediaTitle?.contains("737") == true)
        let c172 = TypeInfoStore.info(forEntryId: "fc172")
        #expect(c172?.wikipediaTitle == "Cessna 172")
        #expect(c172?.wikidataId?.hasPrefix("Q") == true)
        #expect(TypeInfoStore.info(forEntryId: "no-such-entry") == nil)
    }

    @Test func photosAreHttpsWithAllowedLicencesAndCredit() throws {
        let allowed = #/^(Public domain|CC0|CC BY(-SA)? \d\.\d( [a-z]{2})?)$/#
        var photos = 0
        for (key, info) in try bundledFile().entries {
            guard let p = info.photo else { continue }
            photos += 1
            #expect(p.imageURL.scheme == "https", "\(key): image not https")
            #expect(p.imageURL.host?.hasSuffix("wikimedia.org") == true, "\(key): \(p.imageURL)")
            #expect(p.pageURL.scheme == "https", "\(key): page not https")
            #expect(p.pageURL.host == "commons.wikimedia.org", "\(key): \(p.pageURL)")
            #expect(p.license.wholeMatch(of: allowed) != nil, "\(key): licence '\(p.license)'")
            // CC BY / BY-SA need a real author; only public domain / CC0 may
            // ship without one (the card then credits the licence alone).
            if !(p.license == "Public domain" || p.license == "CC0") {
                #expect(!p.artist.isEmpty, "\(key): CC BY photo without an author")
            }
            // Commons boilerplate the generator's clean_artist() strips.
            for junk in ["self", "Unknown"] {
                #expect(p.artist.caseInsensitiveCompare(junk) != .orderedSame, "\(key): artist '\(p.artist)'")
            }
            for junk in ["No machine-readable author", "derivative work", "Original uploader", "(talk)"] {
                #expect(!p.artist.localizedCaseInsensitiveContains(junk), "\(key): artist '\(p.artist)'")
            }
            #expect(!p.artist.contains("<"), "\(key): HTML left in artist")
        }
        #expect(photos > 295)
    }

    /// Common catches that once fell back to the plain sky (2026-10-25: the
    /// Cessna 152's only Wikidata photo is GFDL-only and it was mapped to the
    /// 150's article). The generator now also tries the article's photos.
    @Test func commonGATypesHaveATypePhoto() {
        let c152 = TypeInfoStore.info(forEntryId: "fc152")
        #expect(c152?.wikipediaTitle == "Cessna 152")
        for id in ["fc152", "fsr22", "ftp-pc12", "fb350", "fcp-twinotter", "fe55p", "flj-hondajet"] {
            #expect(TypeInfoStore.info(forEntryId: id)?.photo != nil, "\(id) has no photo")
        }
    }

    @Test func specsArePlausibleWhenPresent() throws {
        for (key, info) in try bundledFile().entries {
            if let y = info.firstFlightYear { #expect((1900...2030).contains(y), "\(key): \(y)") }
            if let n = info.numberBuilt { #expect(n > 0, "\(key): \(n)") }
            if let w = info.wingspanMeters { #expect((3...120).contains(w), "\(key): wingspan \(w)") }
            if let l = info.lengthMeters { #expect((3...100).contains(l), "\(key): length \(l)") }
        }
    }

    // MARK: - Catch → entry

    @Test func b738CatchResolvesToThe737Family() throws {
        let hit = try #require(TypeInfoStore.entry(for: mk(typecode: "B738")))
        #expect(hit.family.id == "fam-737")
        #expect(hit.entry.id == "f737-800")
    }

    @Test func typecodeMatchBeatsAnEarlierTokenMatch() throws {
        // A MAX 8 whose raw model reads "737-8" also token-matches the
        // 737-800 slot ("737-8"); the exact typecode must win.
        let hit = try #require(TypeInfoStore.entry(for: mk(typecode: "B38M", model: "737-8")))
        #expect(hit.entry.id == "f737-max8")
    }

    @Test func unidentifiedCatchMatchesNothing() {
        #expect(TypeInfoStore.entry(for: mk(typecode: nil)) == nil)
        #expect(TypeInfoStore.info(for: mk(typecode: nil)) == nil)
    }

    // MARK: - info(for:) and the dims fallback

    @Test func dimsFallBackToAircraftTypesInMetres() throws {
        // Every 737 variant shares the "Boeing 737 Next Generation" article,
        // so the generator leaves Wikidata specs off and the per-typecode FAA
        // numbers (B738: 112.6 ft span, 129.5 ft long) fill in.
        let info = try #require(TypeInfoStore.info(for: mk(typecode: "B738")))
        #expect(info.entryId == "f737-800")
        #expect(info.wikipediaTitle != nil)
        let span = try #require(info.wingspanMeters)
        let length = try #require(info.lengthMeters)
        #expect(abs(span - 112.6 * 0.3048) < 0.01)
        #expect(abs(length - 129.5 * 0.3048) < 0.01)
    }

    @Test func bundledDimsWinOverTheFallback() throws {
        let bundled = try #require(TypeInfoStore.info(forEntryId: "fc172"))
        let resolved = try #require(TypeInfoStore.info(for: mk(typecode: "C172")))
        if let w = bundled.wingspanMeters { #expect(resolved.wingspanMeters == w) }
        if let l = bundled.lengthMeters { #expect(resolved.lengthMeters == l) }
        #expect(resolved.photo == bundled.photo)
    }

    @Test func unmatchedTypecodeWithDimsReturnsDimsOnlyInfo() throws {
        // Any typecode with FAA dims that fills no family slot.
        let candidates = AircraftNaming.table.keys.sorted().filter { tc in
            AircraftNaming.dimensionsFeet(forTypecode: tc) != nil
                && TypeInfoStore.entry(for: mk(typecode: tc)) == nil
        }
        let tc = try #require(candidates.first)
        let info = try #require(TypeInfoStore.info(for: mk(typecode: tc)))
        #expect(info.entryId == "")
        #expect(info.wikipediaTitle == nil && info.photo == nil)
        #expect(info.wingspanMeters != nil || info.lengthMeters != nil)
    }

    @Test func feetToMetresRoundsToTheCentimetre() {
        #expect(TypeInfoStore.metres(100) == 30.48)
        #expect(TypeInfoStore.metres(36.1) == 11.0)
    }

    @Test func dimensionsAccessorNormalisesTypecode() {
        let d = AircraftNaming.dimensionsFeet(forTypecode: " b738 ")
        #expect(d?.wingspan == 112.6)
        #expect(d?.length == 129.5)
        #expect(AircraftNaming.dimensionsFeet(forTypecode: nil) == nil)
        #expect(AircraftNaming.dimensionsFeet(forTypecode: "ZZZZ") == nil)
    }
}
